// Package main wires the BNPL CLI entrypoint.
//
// It belongs to the adapter layer and delegates process startup to the Cobra
// command package without containing business logic.
//
//	@title						BNPL Backend API
//	@version					1.0
//	@description				HTTP API for the BNPL backend service.
//	@description				The committed Swagger document is a Swagger 2.0 specification generated by Swaggo.
//	@description				Business endpoints under /api/v1 require API Gateway auth headers, except /api/v1/partner endpoints, which authenticate Merchant identity with X-Terminal-Id and X-API-Key. Partner Create Checkout additionally consumes Gateway-injected X-Auth-Tenant-Id and X-Auth-Context-Id (not merchant-selected; not request-body fields). Gateway SubjectID/Permissions do not control Partner Merchant identity. Health probes are public.
//	@BasePath					/
//
//	@securityDefinitions.apikey	PermissionAuth
//	@in							header
//	@name						x-auth-permissions
//	@description				Comma-separated gateway permissions. Protected endpoints also require x-auth-subject-id, x-auth-tenant-id, and x-auth-context-id.
//
//	@securityDefinitions.apikey	TerminalID
//	@in							header
//	@name						X-Terminal-Id
//	@description				Public numeric terminal identifier of an external partner. Sent together with X-API-Key on /api/v1/partner endpoints.
//
//	@securityDefinitions.apikey	TerminalAPIKey
//	@in							header
//	@name						X-API-Key
//	@description				Secret API key of an external partner terminal. Sent together with X-Terminal-Id on /api/v1/partner endpoints. Never logged.
package main

import "github.com/parstis/bnpl-backend/cmd/bnpl/command"

// main executes the root CLI command and exits through Cobra's error handling.
func main() {
	command.Execute()
}

